/// Every path in `paths` at `commit`, in one `git cat-file --batch`.
fn batch_manifest_blobs_at<R: CommandRunner>(
    runner: &R,
    root: &std::path::Path,
    commit: &str,
    paths: &[&str],
) -> Result<Vec<BatchBlob>, GraphError> {
    let objects: Vec<String> = paths.iter().map(|path| format!("{commit}:{path}")).collect();
    batch_blobs(runner, root, &objects)
}

/// The manifests of one commit: those fetched up front in one batch, and any other fetched on first ask. A package that
/// names its workspace with `package.workspace` can name a different one at each of two commits, so the second commit's
/// workspace manifest is not among those fetched for the first.
struct CommitBlobs<'a, R: CommandRunner> {
    runner: &'a R,
    root: &'a std::path::Path,
    commit: &'a str,
    blobs: std::cell::RefCell<std::collections::BTreeMap<String, BatchBlob>>,
}

impl<'a, R: CommandRunner> CommitBlobs<'a, R> {
    fn new(runner: &'a R, root: &'a std::path::Path, commit: &'a str, paths: &[&str], blobs: Vec<BatchBlob>) -> Self {
        CommitBlobs {
            runner,
            root,
            commit,
            blobs: std::cell::RefCell::new(paths.iter().map(|path| (*path).to_owned()).zip(blobs).collect()),
        }
    }

    /// The text of `path` at the commit, `None` when it has none there.
    fn text(&self, path: &str) -> Result<Option<String>, GraphError> {
        if !self.blobs.borrow().contains_key(path) {
            let fetched = batch_manifest_blobs_at(self.runner, self.root, self.commit, &[path])?;
            let blob = fetched.into_iter().next().unwrap_or(BatchBlob::Missing);
            self.blobs.borrow_mut().insert(path.to_owned(), blob);
        }
        Ok(match &self.blobs.borrow()[path] {
            BatchBlob::Blob(text) => Some(text.clone()),
            BatchBlob::Missing => None,
        })
    }
}

fn resolve_batch_versions<R: CommandRunner>(
    commit: &CommitBlobs<'_, R>,
    queries: &[(String, Ecosystem)],
) -> Result<Vec<callisto_manifests::EffectiveManifestVersion>, GraphError> {
    let mut reads = callisto_manifests::WorkspaceReads::default();
    let at_commit = |other: &std::path::Path| -> Result<Option<String>, callisto_model::ManifestError> {
        let unavailable = |message: String| callisto_model::ManifestError::Read {
            path: other.to_path_buf(),
            message,
        };
        let key = normalized_git_path(other).map_err(|error| unavailable(error.to_string()))?;
        commit.text(&key).map_err(|error| unavailable(error.to_string()))
    };
    queries
        .iter()
        .map(|(path, ecosystem)| {
            let Some(source) = commit.text(path)? else {
                return Err(command_malformed_output(
                    "git",
                    &["cat-file", "--batch"],
                    format!("canonical manifest `{path}` was reported missing at the queried commit"),
                ));
            };
            let format = ecosystem
                .canonical_manifest_format()
                .ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: format!("canonical manifest `{path}` has no canonical manifest format"),
                })?;
            callisto_manifests::read_effective_version(
                format,
                &source,
                std::path::Path::new(path),
                &mut reads,
                at_commit,
            )
            .map_err(historical_manifest_error)?
            .ok_or_else(|| {
                command_malformed_output(
                    "git",
                    &["cat-file", "--batch"],
                    format!("manifest `{path}` has no effective declared version"),
                )
            })
        })
        .collect()
}

fn reason_from_bump(
    reason: Option<&BumpReason>,
    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
) -> Result<ReleaseInclusionReason, GraphError> {
    match reason {
        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
            group_id: group.to_string(),
        }),
        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
            Ok(ReleaseInclusionReason::FixedGroup {
                group_id: group.to_string(),
            })
        }
        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
        Some(BumpReason::Cascade { via, dep_kind, .. }) => {
            // `package_ids` is derived from the same workspace graph `via`
            // was resolved against, so a miss (or a non-unique release
            // identity) here means that pairing broke, not that this is a
            // recoverable operator condition.
            let source = package_ids
                .get(via)
                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
                .ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: format!(
                        "cascade source package `{}` has no unique release package id",
                        via.display_name()
                    ),
                })?;
            Ok(ReleaseInclusionReason::Cascade {
                from: source,
                edge_kind: format!("{dep_kind:?}"),
            })
        }
        Some(BumpReason::PeerEscalation { via, .. }) => {
            let source = package_ids
                .get(via)
                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
                .ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: format!(
                        "peer-escalation source package `{}` has no unique release package id",
                        via.display_name()
                    ),
                })?;
            Ok(ReleaseInclusionReason::Cascade {
                from: source,
                edge_kind: "peer".to_string(),
            })
        }
        Some(_) => Err(GraphError::UnsupportedRelease {
            feature: UnsupportedReleaseFeature::BumpReason,
        }),
    }
}

#[cfg(test)]
mod tests {
    use callisto_model::{Ecosystem, Version};

    use super::*;

    #[test]
    fn decision_is_canonical_and_ecosystem_qualified() {
        let cargo = ReleasePackageId::new(Ecosystem::Cargo, "demo").unwrap();
        let npm = ReleasePackageId::new(Ecosystem::Npm, "demo").unwrap();
        let first = ReleaseDecisionV1::new(vec![
            ReleaseDecisionEntry {
                package: npm,
                target_version: Version::semver(1, 0, 0),
                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
            },
            ReleaseDecisionEntry {
                package: cargo,
                target_version: Version::semver(1, 0, 0),
                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
            },
        ])
        .unwrap();
        assert_eq!(first.entries[0].package.to_string(), "cargo/demo");
        assert_ne!(first.entries[0].package, first.entries[1].package);
    }

    #[test]
    fn release_commit_delta_parser_accepts_only_unambiguous_path_statuses() {
        let args = ["diff-tree", "--name-status"];
        assert_eq!(
            parse_name_status("M\tCargo.toml\nD\t.changeset/release.md\n", &args).unwrap(),
            vec![
                ("M".to_string(), "Cargo.toml".to_string()),
                ("D".to_string(), ".changeset/release.md".to_string()),
            ]
        );
        assert!(parse_name_status("R100\told\tnew\n", &args).is_err());
        assert!(parse_name_status("M Cargo.toml\n", &args).is_err());
    }

    #[test]
    fn changeset_path_matches_only_direct_child_markdown_files() {
        assert!(is_changeset_path(".changeset/release.md", ".changeset"));
        assert!(!is_changeset_path(".changeset/README.md", ".changeset"));
        assert!(!is_changeset_path(".changeset/nested/release.md", ".changeset"));
        assert!(!is_changeset_path(".changesets/release.md", ".changeset"));
    }

    #[test]
    fn root_changeset_dir_matches_only_root_level_markdown_files() {
        assert!(is_changeset_path("release.md", ""));
        assert!(!is_changeset_path("README.md", ""));
        assert!(!is_changeset_path("docs/notes.md", ""));
        assert!(!is_changeset_path("nested/release.md", ""));
    }

    /// Regression: both malformed name-status lines must
    /// surface as `GraphError::ReleaseCommand` (E164) with a
    /// `CommandFailure::MalformedOutput` cause naming the real `git`
    /// program/args, not the old fieldless `ReleaseIntentStale`.
    #[test]
    fn release_commit_delta_parser_reports_malformed_output_not_stale_intent() {
        let args = ["diff-tree", "--name-status"];
        let err = parse_name_status("R100\told\tnew\n", &args).unwrap_err();
        match err {
            GraphError::ReleaseCommand {
                program,
                failure: CommandFailure::MalformedOutput { .. },
                ..
            } => assert_eq!(program, "git"),

